a:\"Buyer Invoice Amount\"::STRING AS Buyer_Invoice_Amount, _airbyte_data:\"Order Shipped From (State)\"::STRING AS Order_Shipped_From__State, _airbyte_data:\"Bank Offer Share\"::STRING AS Bank_Offer_Share, _airbyte_data:\"Business Name\"::STRING AS Business_Name, _airbyte_data:\"Customer_s Delivery Pincode\"::STRING AS Customer_Delivery_Pincode, _airbyte_data:\"Item Quantity\"::STRING AS Item_Quantity, _airbyte_data:\"Beneficiary Name\"::STRING AS Beneficiary_Name, _airbyte_data:\"SGST Rate (or UTGST as applicable)\"::STRING AS SGST_Rate__or_UTGST_as_applicable, _airbyte_data:\"Order Date\"::STRING AS Order_Date, _airbyte_data:\"Buyer Invoice ID\"::STRING AS Buyer_Invoice_ID, _airbyte_data:\"Business GST Number\"::STRING AS Business_GST_Number, _airbyte_data:\"IGST Rate\"::STRING AS IGST_Rate, _airbyte_data:\"Final Invoice Amount (Price after discount+Shipping Charges)\"::STRING AS Final_Invoice_Amount__Price_after_discount_Shipping_Charges, _airbyte_data:\"TCS SGST Amount\"::STRING AS TCS_SGST_Amount, _airbyte_data:\"SGST Amount (Or UTGST as applicable)\"::STRING AS SGST_Amount__Or_UTGST_as_applicable, _airbyte_data:\"Order Item ID\"::STRING AS Order_Item_ID, _airbyte_data:\"CST Rate\"::STRING AS CST_Rate, _airbyte_data:\"Luxury Cess Rate\"::STRING AS Luxury_Cess_Rate, _airbyte_data:\"IMEI\"::STRING AS IMEI, _airbyte_data:\"Order Type\"::STRING AS Order_Type, _airbyte_data:\"VAT Rate\"::STRING AS VAT_Rate, _airbyte_data:\"TCS SGST Rate\"::STRING AS TCS_SGST_Rate, _airbyte_data:\"Seller GSTIN\"::STRING AS Seller_GSTIN, _airbyte_data:\"Order Approval Date\"::STRING AS Order_Approval_Date, _airbyte_data:\"TDS Amount\"::STRING AS TDS_Amount, _airbyte_data:\"SKU\"::STRING AS SKU, _airbyte_data:\"Event Sub Type\"::STRING AS Event_Sub_Type FROM appldatabase.maplemonk._airbyte_raw_alphanso_Flipkart_Seller_sales QUALIFY DENSE_RANK() OVER ( PARTITION BY _airbyte_data:\"Order ID\"::STRING, _airbyte_data:\"Order Item ID\"::STRING, _airbyte_data:\"Event Type\"::STRING, _airbyte_data:\"Event Sub Type\"::STRING ORDER BY DATE_TRUNC(\'SECOND\', _airbyte_emitted_at) DESC ) = 1; Create or replace table appldatabase.maplemonk.alphanso_flipkart_fact_items as SELECT CASE WHEN s.Fulfilment_Type = \'NON_FBF\' THEN \'Flipkart NON-FBF\' ELSE \'Flipkart FBF\' END AS shop_name, s.order_id, s.order_id AS order_name, NULL AS customer_id, NULL AS phone, HSN_Code, s.order_type AS payment_type, CAST(NULL AS STRING) AS tags, s.Order_Item_ID AS line_item_id, CAST(REPLACE(REPLACE(s.sku, \'\"\', \'\'), \'SKU:\', \'\') AS STRING) AS SKU, REPLACE(s.FSN, \'\"\', \'\') AS product_id, CASE WHEN s.Event_Type = \'Return\' THEN 1 ELSE 0 END AS is_refund, CASE WHEN s.Customer_Delivery_State = \'-\' THEN (CASE WHEN s.Customer_Billing_State = \'-\' THEN NULL ELSE s.Customer_Billing_State END) ELSE s.Customer_Delivery_State END AS state, CASE WHEN s.Customer_Delivery_Pincode = \'-\' THEN (CASE WHEN s.Customer_Billing_Pincode = \'-\' THEN NULL ELSE s.Customer_billing_Pincode END) ELSE s.Customer_Delivery_Pincode END AS pincode, REPLACE(Product_Title_Description, \'\"\', \'\') AS PRODUCT_NAME, CAST(NULL AS STRING) AS category, TRY_CAST(LEFT(s.order_date, 10) AS DATE) AS order_date, TRY_CAST(LEFT(s.Buyer_Invoice_Date, 10) AS DATE) AS invoice_Date, f.delivery_date, f.cancellation_date, f.manifest_date, f.dispatch_date, f.return_approval_date, f.return_reason, f.return_sub_reason, f.order_service_completion_date, f.order_item_status, f.return_id, f.fulfilment_type, f.fulfilment_source, f.cancellation_reason, f.payment_mode, CAST(tds_rate AS FLOAT) AS tds_rate, CAST(VAT_Rate AS FLOAT) AS VAT_Rate, CAST(CGST_Rate AS FLOAT) AS CGST_Rate, CAST(IGST_Rate AS FLOAT) AS IGST_Rate, CAST(CST_Amount AS FLOAT) AS CST_Amount, CASE WHEN TDS_Amount <> \'NA\' THEN CAST(TDS_Amount AS FLOAT) ELSE NULL END AS TDS_Amount, CAST(VAT_Amount AS FLOAT) AS VAT_Amount, CAST(CGST_Amount AS FLOAT) AS CGST_Amount, CAST(IGST_Amount AS FLOAT) AS IGST_Amount, CAST(Type_of_tax AS FLOAT) AS Type_of_tax, CASE WHEN Usual_Price <> \'NA\' AND Usual_Price <> \'false\' THEN CAST(Usual_Price AS FLOAT) ELSE NULL END AS Usual_Price, Seller_GSTIN, ABS(IFNULL(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0)) AS line_item_sales, ABS(IFNULL(CAST(Shipping_Charges AS FLOAT), 0)) AS shipping_price, ABS(IFNULL(CAST(Item_Quantity AS FLOAT), 0)) AS quantity, ABS(IFNULL(TRY_CAST(Total_TCS_Deducted AS FLOAT), 0)) AS tax, ABS(DIV0NULL( IFNULL(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0), (IFNULL(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0) + IFNULL(TRY_CAST(Total_TCS_Deducted AS FLOAT), 0)) )) AS overall_tax_rate, ABS(IFNULL(CAST(Total_Discount AS FLOAT), 0)) AS discount, DIV0NULL( ABS(IFNULL(CAST(Total_Discount AS FLOAT), 0)), (1 - DIV0NULL( ABS(IFNULL(TRY_CAST(Total_TCS_Deducted AS FLOAT), 0)), (ABS(IFNULL(TRY_CAST(Total_TCS_Deducted AS FLOAT), 0)) + ABS(IFNULL(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0))) )) ) AS discount_before_tax, (ABS(IFNULL(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0)) - DIV0NULL( ABS(IFNULL(CAST(Total_Discount AS FLOAT), 0)), (1 - DIV0NULL( ABS(IFNULL(TRY_CAST(Total_TCS_Deducted AS FLOAT), 0)), (ABS(IFNULL(TRY_CAST(Total_TCS_Deducted AS FLOAT), 0)) + ABS(IFNULL(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0))) )) )) AS gross_sales_before_tax, ABS(IFNULL(CAST(Price_after_discount__Price_before_discount_Total_discount AS FLOAT), 0)) AS total_sales, CASE WHEN Is_Shopsy_Order <> \'0.1\' AND CAST(Is_Shopsy_Order AS BOOLEAN) = TRUE THEN \'Shopsy Order\' ELSE \'Flipkart Order\' END AS Order_Channel, Beneficiary_Name AS name, CAST(NULL AS STRING) AS email, Order_Shipped_From__State AS Order_Shipped_From_State, Warehouse_ID, Business_Name, f.courier, f.fk_awb FROM ( SELECT * FROM appldatabase.maplemonk.flipkart_Seller_alphanso_sales_flattened WHERE LOWER(Event_Sub_Type) = \'sale\' ) s LEFT JOIN appldatabase.maplemonk.alphanso_flipkart_order_fulfilment_fact_items f ON f.order_id = s.order_id AND f.order_item_id = s.order_item_id;",
